package com.example.salarygrows;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;import java.time.*;import java.text.*;import java.util.*;
public class SalaryWidget extends AppWidgetProvider {
 public static class Mini extends SalaryWidget {} public static class Wide extends SalaryWidget {}
 public static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);for(Class<?> cl:new Class<?>[]{SalaryWidget.class,Mini.class,Wide.class}){int[] ids=m.getAppWidgetIds(new ComponentName(c,cl));if(ids.length>0)render(c,m,ids,cl);}}
 static void render(Context c,AppWidgetManager m,int[] ids,Class<?> cl){SharedPreferences p=c.getSharedPreferences("salary",Context.MODE_PRIVATE);boolean transparent=p.getBoolean("transparent_bg",false);long target=p.getLong("salary_amount",p.getLong("net",2500000));LocalDateTime n=LocalDateTime.now();int days=YearMonth.from(n).lengthOfMonth();double f=((n.getDayOfMonth()-1)*86400d+n.getHour()*3600d+n.getMinute()*60d+n.getSecond())/(days*86400d);int layout=cl==Mini.class?R.layout.salary_widget_mini:cl==Wide.class?R.layout.salary_widget_wide:R.layout.salary_widget;for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),layout);v.setInt(R.id.widget_root,"setBackgroundResource",transparent?R.drawable.widget_bg_transparent:R.drawable.widget_bg);v.setTextViewText(R.id.title,"월급이 자란다 💵");v.setTextViewText(R.id.amount,NumberFormat.getIntegerInstance(Locale.KOREA).format((long)(target*f))+"원");v.setTextViewText(R.id.progress_text,cl==SalaryWidget.class?String.format(Locale.KOREA,"달성률 %.2f%%",f*100):String.format(Locale.KOREA,"%.1f%%",f*100));v.setProgressBar(R.id.progress,10000,(int)Math.round(f*10000),false);PendingIntent pi=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.widget_root,pi);m.updateAppWidget(id,v);}}
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){render(c,m,ids,getClass());}
}